<template>
  <div class="tpv-root">
    <!-- ── Navigation Drawer ────────────────────────────────────────────── -->
    <v-navigation-drawer
      app
      class="primary darken-1 white--text"
      clipped
      permanent
      right
      style="z-index: 3;"
    >
      <v-list class="white--text">
        <v-list-item>
          <v-btn class="primary" dark @click="goBack">
            <v-icon light left>mdi-arrow-left</v-icon>
            <span>{{ backLabel }}</span>
          </v-btn>
        </v-list-item>
      </v-list>

      <template v-if="!loading && !error">
        <v-divider color="white"></v-divider>
        <v-subheader class="white--text"><h2>Sections</h2></v-subheader>
        <v-list-item
          v-for="section in sectionMenu"
          :key="section.name"
          @click="scrollTo(section.name)"
        >
          <v-list-item-content class="white--text">
            <v-list-item-title class="text-uppercase">
              <h4>{{ section.title }}</h4>
            </v-list-item-title>
            <v-list-item-subtitle class="white--text">
              {{ section.desc }}
            </v-list-item-subtitle>
          </v-list-item-content>
        </v-list-item>
      </template>
    </v-navigation-drawer>

    <main class="tpv-body">
      <!-- ── Loading ──────────────────────────────────────────────────── -->
      <div v-if="loading" class="tpv-loading">
        <v-progress-circular
          indeterminate
          color="primary"
          size="48"
        ></v-progress-circular>
        <span>Loading training plan request…</span>
      </div>

      <!-- ── Error ────────────────────────────────────────────────────── -->
      <v-alert
        v-else-if="error"
        type="error"
        outlined
        prominent
        border="left"
        class="mb-4"
      >
        {{ error }}
      </v-alert>

      <template v-else>
        <!-- ── Hero summary ───────────────────────────────────────────── -->
        <section class="tpv-hero">
          <div class="tpv-hero__main">
            <div class="tpv-hero__avatar">
              <v-icon size="30" color="white">mdi-clipboard-text-outline</v-icon>
            </div>
            <div class="tpv-hero__info">
              <div class="tpv-hero__label">Training Plan Request</div>
              <h1 class="tpv-hero__name">
                {{ requestData.course || "Untitled Course" }}
              </h1>
              <div class="tpv-hero__sub">
                <v-icon size="14" color="#a8a29e">mdi-target</v-icon>
                {{ trainingNeedTitle || "Training need not specified" }}
              </div>
            </div>
          </div>
          <div class="tpv-hero__chips">
            <v-chip
              v-if="requestData.trainingTypeDisplay"
