            >
              <v-icon left x-small>mdi-school-outline</v-icon>
              {{ requestData.trainingTypeDisplay }}
            </v-chip>
            <span
              class="tpv-status-pill"
              :class="'tpv-status-pill--' + statusKey(requestData.status)"
            >
              <span class="tpv-status-pill__dot"></span>
              {{ requestData.statusDisplay || "Pending" }}
            </span>
          </div>
        </section>

        <v-row>
          <v-col cols="12" lg="7">
        <!-- ── Request Overview ─────────────────────────────────────────── -->
        <v-card id="section-overview" outlined class="tpv-card mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center py-3"
          >
            <v-icon left color="white">mdi-information-outline</v-icon>
            Request Overview
          </v-card-title>
          <v-card-text class="pa-4">
            <v-row dense class="mb-3">
              <v-col cols="12" md="6">
                <div class="tpv-label">STAFF MEMBER</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-account</v-icon>
                  {{ practitionerName || "Unknown" }}
                </div>
              </v-col>
              <v-col cols="12" md="6">
                <div class="tpv-label">TRAINING NEED</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-target</v-icon>
                  {{ trainingNeedTitle || "Not specified" }}
                </div>
                <div v-if="trainingNeedDescription" class="text-caption mt-1">
                  {{ trainingNeedDescription }}
                </div>
              </v-col>
            </v-row>

            <v-divider class="my-2"></v-divider>

            <v-row dense class="mb-3">
              <v-col cols="12" md="6">
                <div class="tpv-label">COURSE/PROGRAM</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-book-open-variant</v-icon>
                  {{ requestData.course || "Not specified" }}
                </div>
                <v-chip
                  v-if="requestData.qualificationLevel"
                  x-small
                  outlined
                  color="blue darken-1"
                  class="mt-1"
                >
                  {{ requestData.qualificationLevel }}
                </v-chip>
              </v-col>
              <v-col cols="12" md="6">
                <div class="tpv-label">TRAINING INSTITUTION</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-domain</v-icon>
                  {{ requestData.institution || "Not specified" }}
                </div>
              </v-col>
            </v-row>

            <v-divider class="my-2"></v-divider>

            <v-row dense class="mb-3">
              <v-col cols="12" md="3">
                <div class="tpv-label">LEARNING METHODOLOGY</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-laptop</v-icon>
                  {{ requestData.methodologyDisplay || "Not specified" }}
                </div>
              </v-col>
              <v-col cols="12" md="3">
                <div class="tpv-label">START DATE</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-calendar-start</v-icon>
                  {{ formatDate(requestData.startdate) }}
                </div>
              </v-col>
              <v-col cols="12" md="3">
                <div class="tpv-label">END DATE</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-calendar-end</v-icon>
                  {{ formatDate(requestData.enddate) }}
                </div>
              </v-col>
              <v-col cols="12" md="3">
                <div class="tpv-label">SUBMITTED</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-calendar</v-icon>
                  {{ formatDate(requestData.submissionDate) }}
                </div>
              </v-col>
            </v-row>

            <template v-if="requestData.comments">
              <v-divider class="my-2"></v-divider>
              <div class="tpv-label mb-2">STAFF COMMENTS</div>
              <v-card outlined class="pa-3">
                <p class="text-body-1 font-weight-medium mb-0">
                  {{ requestData.comments }}
                </p>
              </v-card>
            </template>
          </v-card-text>
        </v-card>
          </v-col>

          <!-- ── Review Timeline ──────────────────────────────────────────── -->
          <v-col cols="12" lg="5">
        <section id="section-timeline" class="tpv-section tpv-section--sticky">
          <div class="tpv-section__head">
            <div class="tpv-section__title">
              <v-icon size="18" color="#1c1917" class="mr-1">mdi-history</v-icon>
              Review Timeline
            </div>
            <div class="tpv-section__sub">
              Track the approval progress through each review stage
            </div>
          </div>

          <v-alert
            v-if="
              !supervisorReview.status &&
                !hodReview.status &&
                !hrReview.status &&
                !psReview.status
            "
            type="info"
            outlined
            dense
          >
            No reviews have been submitted yet.
          </v-alert>

          <div v-else class="timeline-container">
            <div
              v-for="stage in timelineStages"
              :key="stage.name"
              class="timeline-item"
              :class="{ 'timeline-active': stage.review.status }"
            >
              <div class="timeline-marker">
                <v-avatar
                  :color="stage.review.status ? stage.color : 'grey lighten-2'"
                  size="44"
                >
                  <v-icon :color="stage.review.status ? 'white' : 'grey'">
                    {{ stage.icon }}
                  </v-icon>
                </v-avatar>
              </div>
              <v-card
                outlined
                class="timeline-card"
                :class="{ 'card-completed': stage.review.status }"
              >
                <v-card-title class="py-2 px-4 tpv-timeline-card-title">
                  <span class="font-weight-bold">{{ stage.title }}</span>
                  <v-spacer></v-spacer>
                  <span
                    v-if="stage.review.status"
                    class="tpv-status-pill tpv-status-pill--sm"
                    :class="
                      'tpv-status-pill--' + statusKey(stage.review.status.code)
                    "
                  >
                    <span class="tpv-status-pill__dot"></span>
                    {{ stage.review.status.display }}
                  </span>
                  <span v-else class="tpv-status-pill tpv-status-pill--none tpv-status-pill--sm">
                    <span class="tpv-status-pill__dot"></span>
                    Pending
                  </span>
                </v-card-title>
                <v-card-text v-if="stage.review.status" class="pa-4">
                  <div class="d-flex align-center mb-2">
                    <v-icon small color="grey" class="mr-2">mdi-calendar</v-icon>
                    <span class="caption grey--text">
                      {{ formatDate(stage.review.date) }}
                    </span>
                  </div>
                  <div v-if="stage.review.comments" class="timeline-comment">
                    <v-icon small color="grey darken-1" class="mr-2"
                      >mdi-message-text</v-icon
                    >
                    <span class="body-2">{{ stage.review.comments }}</span>
                  </div>
                </v-card-text>
                <v-card-text v-else class="pa-4 text-center grey--text">
                  <v-icon color="grey lighten-1" small>mdi-clock-outline</v-icon>
                  <span class="caption ml-1">Awaiting review</span>
                </v-card-text>
              </v-card>
            </div>
          </div>
        </section>
          </v-col>
        </v-row>
      </template>
    </main>
  </div>
</template>

<script>
export default {
  name: "TrainingPlanReview",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      requestData: {
        id: "",
        practitionerId: "",
        trainingNeedId: "",
        trainingType: "",
        trainingTypeDisplay: "",
        methodology: "",
        methodologyDisplay: "",
        course: "",
        qualificationLevel: "",
        institution: "",
        comments: "",
        status: "",
        statusDisplay: "",
        submissionDate: "",
        startdate: "",
        enddate: "",
      },
      hodReview: { status: null, date: "", comments: "" },
      supervisorReview: { status: null, date: "", comments: "" },
      hrReview: { status: null, date: "", comments: "" },
      psReview: { status: null, date: "", comments: "" },

      practitionerName: "",
      trainingNeedTitle: "",
      trainingNeedDescription: "",
    };
  },

  computed: {
    backLabel() {
      return (this.queries && this.queries.returnLabel) || "Back";
    },

    requestId() {
      return this.queries?.request;
    },

    practitionerId() {
      return this.queries?.practitioner || this.$route.query.practitioner;
    },

    sectionMenu() {
      return [
        {
          name: "overview",
          title: "Overview",
          desc: "Course and request details",
        },
        {
          name: "timeline",
          title: "Review Timeline",
          desc: "Approval progress",
        },
      ];
    },

    timelineStages() {
      return [
        {
          name: "supervisor",
          title: "Supervisor Review",
          icon: "mdi-account-tie",
          color: "orange",
          review: this.supervisorReview,
        },
        {
          name: "hod",
          title: "HOD Review",
          icon: "mdi-account-star",
          color: "deep-purple",
          review: this.hodReview,
        },
        {
          name: "hr",
          title: "HR Review",
          icon: "mdi-office-building",
          color: "blue",
          review: this.hrReview,
        },
        {
          name: "ps",
          title: "PS Review",
          icon: "mdi-crown",
          color: "purple",
          review: this.psReview,
        },
      ];
    },
  },

  created() {
    this.loadAll();
  },

  methods: {
    async loadAll() {
      this.loading = true;
      this.error = null;

      if (!this.requestId) {
        this.error = "No training plan request specified.";
        this.loading = false;
        return;
      }

      try {
        await this.loadRequestData();
        await this.getReviews();
      } catch (err) {
        console.error("Error loading training plan request:", err);
        this.error = err.message || "Failed to load request details";
      } finally {
        this.loading = false;
      }
    },

    async getReviews() {
      try {
        const response = await fetch(
          `/fhir/Basic?trainplanrequest=Basic/${this.requestId}&_profile=http://ihris.org/fhir/StructureDefinition/supervisor-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/hod-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/hr-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/ps-training-plan-review-profile`,
        );
        const result = await response.json();
        if (result.entry) {
          result.entry.forEach((entry) => {
            const resource = entry.resource;
            const profile = resource.meta?.profile?.[0];
            const reviewData = {
              status: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/review-status",
              )?.valueCoding,
              date: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/event-date",
              )?.valueDate,
              comments: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/comments",
              )?.valueString,
            };
            if (profile) {
              if (profile.includes("supervisor-training-plan-review-profile")) {
                this.supervisorReview = reviewData;
              } else if (profile.includes("hod-training-plan-review-profile")) {
                this.hodReview = reviewData;
              } else if (profile.includes("hr-training-plan-review-profile")) {
                this.hrReview = reviewData;
              } else if (profile.includes("ps-training-plan-review-profile")) {
                this.psReview = reviewData;
              }
            }
          });
        }
      } catch (error) {
        console.error("Error fetching other reviews:", error);
      }
    },

    async loadRequestData() {
      const response = await fetch(`/fhir/Basic/${this.requestId}`);
      if (!response.ok) throw new Error("Training plan request not found");
      const request = await response.json();

      const needExt = request.extension.find(
        (ext) =>
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/training-need-reference",
      );
      if (needExt && needExt.valueReference) {
        this.requestData.trainingNeedId = needExt.valueReference.reference.split(
          "/",
        )[1];
        await this.loadTrainingNeed(this.requestData.trainingNeedId);
      }

      const typeExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/training-type",
      );
      if (typeExt && typeExt.valueCoding) {
        this.requestData.trainingType = typeExt.valueCoding.code;
        this.requestData.trainingTypeDisplay = typeExt.valueCoding.display;
      }

      const durationExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/duration",
      );
      if (durationExt) {
        this.requestData.duration = durationExt.valueInteger;
      }

      const methodExt = request.extension.find(
        (ext) =>
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/learning-methodology",
      );
      if (methodExt && methodExt.valueCoding) {
        this.requestData.methodology = methodExt.valueCoding.code;
        this.requestData.methodologyDisplay = methodExt.valueCoding.display;
      }

      const qualNameExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
      );
      this.requestData.course = qualNameExt?.valueString;
      const qualLevelExt = request.extension.find(
        (ext) =>
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/qualification-level",
      );
      this.requestData.qualificationLevel =
        qualLevelExt?.valueCoding?.display || qualLevelExt?.valueCoding?.code || "";

      const instExt = request.extension.find(
        (ext) =>
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/planning-institution",
      );
      if (instExt) {
        this.requestData.institution = instExt.valueString;
      }

      const commentsExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/comments",
      );
      if (commentsExt) {
        this.requestData.comments = commentsExt.valueString;
      }

      const statusExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/request-status",
      );
      if (statusExt && statusExt.valueCoding) {
        this.requestData.status = statusExt.valueCoding.code;
        this.requestData.statusDisplay = statusExt.valueCoding.display;
      }

      const dateExt = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/event-date",
      );
      if (dateExt) {
        this.requestData.submissionDate = dateExt.valueDate;
      }

      this.requestData.startdate = request.extension.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/start-date",
      )?.valueDate;

      this.requestData.enddate = request.extension.find(
        (ext) => ext.url === "http://ihris.org/fhir/StructureDefinition/end-date",
      )?.valueDate;

      const practExt = request.extension.find(
        (ext) =>
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      );
      if (practExt && practExt.valueReference) {
        this.requestData.practitionerId = practExt.valueReference.reference.split(
          "/",
        )[1];
        await this.loadPractitioner(this.requestData.practitionerId);
      }

      this.requestData.id = request.id;
    },

    async loadPractitioner(practitionerId) {
      try {
        const response = await fetch(
          `/fhir/Practitioner/${practitionerId}?_elements=name`,
        );
        const practitioner = await response.json();
        if (practitioner.name && practitioner.name.length > 0) {
          const name = practitioner.name[practitioner.name.length - 1];
          this.practitionerName = `${
            name.given ? name.given.join(" ") : ""
          } ${name.family || ""}`.trim();
        }
      } catch (error) {
        console.error("Error loading practitioner:", error);
      }
    },

    async loadTrainingNeed(needId) {
      try {
        const response = await fetch(`/fhir/Basic/${needId}`);
        const need = await response.json();

        const nameExt = need.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        );
        if (nameExt) {
          this.trainingNeedTitle = nameExt.valueString;
        }

        const descExt = need.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/description",
        );
        if (descExt) {
          this.trainingNeedDescription = descExt.valueString;
        }
      } catch (error) {
        console.error("Error loading training need:", error);
      }
    },

    // ── Display helpers ─────────────────────────────────────────────────
    statusKey(code) {
      const map = {
        approved: "done",
        rejected: "error",
        undersupervisorreview: "warn",
        underhodreview: "warn",
        underhrreview: "warn",
        underpsreview: "warn",
        pending: "warn",
      };
      return map[code] || "none";
    },

    getTrainingTypeColor(type) {
      const colors = {
        long: "indigo",
        short: "teal",
        parttime: "purple",
      };
      return colors[type] || "grey";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    // ── Navigation ───────────────────────────────────────────────────────
    goBack() {
      if (this.queries && this.queries.returnPath) {
        this.$router.push({
          path: this.queries.returnPath,
          query: this.queries.returnQuery
            ? JSON.parse(this.queries.returnQuery)
            : undefined,
        });
      } else if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    scrollTo(section) {
      const el = document.getElementById(`section-${section}`);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },
  },
};
</script>

